text:
html:has(.pricing-page) {
  background: var(--pricing-bg);
  color-scheme: light;
}
html[data-theme="dark"]:has(.pricing-page) {
  color-scheme: dark;
}
.pricing-page {
  --separator: color-mix(in srgb, var(--pricing-muted) 85%, transparent);
  --bg: var(--pricing-bg);
  padding-block: env(safe-area-inset-top, 0px) env(safe-area-inset-bottom, 0px);
}
.pricing-shell :is(a, button, [tabindex]):focus-visible {
  outline: 2px solid var(--pricing-accent);
  outline-offset: 2px;
}
.pricing-shell a:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.pricing-page,
:where(.pricing-shell :not(button, .button-interaction)),
html:has(.pricing-page) {
  transition:
    background-color 250ms,
    color 250ms,
    border-color 250ms;
}
@media (prefers-reduced-motion: reduce) {
  .pricing-page,
  .pricing-page *,
  html:has(.pricing-page) {
    transition: none !important;
    animation: none !important;
    scroll-behavior: auto !important;
  }
}

/* Pricing uses the landing logo and header frame. */
.pricing-page .pricing-nav {
  --tx: var(--color-pricing-tx-6);
  --mu: var(--color-pricing-mu-7);
  --pk: var(--color-pricing-pk-9);
  --grad: linear-gradient(
    135deg,
    var(--color-pricing-grad-12),
    var(--color-pricing-pk-9)
  );
}
.pricing-page .pricing-nav :is(a, button):focus-visible {
  outline: 2px solid var(--pk);
  outline-offset: 4px;
}
[data-theme="light"] .pricing-page .pricing-nav {
  --tx: var(--color-pricing-tx-18);
  --mu: var(--color-pricing-mu-19);
  --pk: var(--color-pricing-pk-21);
}
html[data-appearance="vercel"] .pricing-page .pricing-nav {
  --tx: var(--color-pricing-tx-35);
  --mu: var(--color-pricing-mu-36);
  --pk: var(--tx);
  font-family: Arial, Helvetica, system-ui, sans-serif;
}
html[data-appearance="vercel"][data-theme="dark"] .pricing-page .pricing-nav {
  --tx: var(--color-pricing-tx-46);
  --mu: var(--color-pricing-line2-34);
}
html:has(.pricing-page) {
  --scrollbar-thumb: var(--pricing-muted);
  --scrollbar-track: var(--pricing-bg);
}
